import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"PhyAgentOS: A Self-Evolving Operating System for Embodied Agents with Decoupled Cognitive Planning and Physical Execution","description":"","frontmatter":{"title":"PhyAgentOS: A Self-Evolving Operating System for Embodied Agents with Decoupled Cognitive Planning and Physical Execution","arxiv":"2607.16636","date":"2026-07-18","authors":"Yang Liu, Weixing Chen, Xinshuai Song, Tao Pu, Siwen Mo, Yongjie Bai, Zihao Chen, Qianran Sun, Liruo Zhong, Ying Shen, Liang Lin","categories":"cs.RO","topics":"世界模型, 具身智能体系统, 语义验证","outline":[2,2]},"headers":[],"relativePath":"papers/2607.16636.md","filePath":"papers/2607.16636.md","lastUpdated":null}'),e={name:"papers/2607.16636.md"};function l(i,s,r,m,c,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="phyagentos-a-self-evolving-operating-system-for-embodied-agents-with-decoupled-cognitive-planning-and-physical-execution" tabindex="-1">PhyAgentOS: A Self-Evolving Operating System for Embodied Agents with Decoupled Cognitive Planning and Physical Execution <a class="header-anchor" href="#phyagentos-a-self-evolving-operating-system-for-embodied-agents-with-decoupled-cognitive-planning-and-physical-execution" aria-label="Permalink to &quot;PhyAgentOS: A Self-Evolving Operating System for Embodied Agents with Decoupled Cognitive Planning and Physical Execution&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2607.16636" target="_blank" rel="noreferrer">2607.16636</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-07-18</td></tr><tr><td><strong>作者</strong></td><td>Yang Liu, Weixing Chen, Xinshuai Song, Tao Pu, Siwen Mo, Yongjie Bai, Zihao Chen, Qianran Sun, Liruo Zhong, Ying Shen, Liang Lin</td></tr><tr><td><strong>分类</strong></td><td>cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>把认知与物理执行之间的边界做成文件系统，以 session 而非单个动作为调度与验收的最小单元，用证据裁决取代&quot;控制器返回成功&quot;，让失败经验沉淀成可检索的知识而不必重训任何神经网络。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/world-models">世界模型</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>论文开篇的场景很具体：让机器人抓杯子，夹爪合在了空气上。VLA 控制器记录轨迹在容差内完成，world model 确认预测状态与观测一致，agentic planner 报告所有工具调用无错误返回。每一层都报成功，杯子却不在手里。</p><p>这不是边角情况，而是当代具身系统的一个结构性缺陷：<strong>没有任何架构层负责验证意图是否在物理世界中实现</strong>。从自然语言指令到电机命令的流水线基本是单向设计——planner 分解目标、模型生成动作、执行器跟踪轨迹——没有组件被指派去做语义验证。于是&quot;执行终止&quot;被当成&quot;任务完成&quot;，控制器的成功返回码被当成目标达成的证据，产生系统性的自欺：执行轨迹正常终止，环境状态却不满足目标。</p><p>作者进一步指出一个常见误解：机器人通信层不等于操作系统。ROS 提供发布订阅的通信骨干，但不原生提供任务级调度、跨会话持久记忆、任务完成的语义验证，以及统一的分层安全架构；安全通常靠急停这类底层保护单独实现。具身 AI 的操作系统必须位于这层中间件<strong>之上</strong>，把调度、内存、验证、安全作为一等服务提供。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>VLA 模型</strong>：从 CLIPort、BC-Z、Gato、RT-1 到跨机器人的 RT-X、RoboCat、Octo，再到 RT-2、OpenVLA 证明大规模视觉语言预训练带来强泛化，以及 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 这类把动作轨迹建模成生成过程的流/扩散方法、GR00T N1 这类通用人形基础模型。它们共享一种结构性不透明：动作失败时，单体架构几乎不提供&quot;错在视觉误感知、策略泛化失败、还是执行动力学&quot;的诊断信号。</p><p><strong>World models</strong>：从 PlaNet、Dreamer 系到 MuZero、TD-MPC2，再到 Genie 的可控生成环境、UniPi 的文本引导视频策略学习、RoboDreamer 的组合式想象、Envisioner、DINO-WM、DreamGen、UniSim。作者的批评是这些仍是<strong>模型级机制</strong>，不是系统级方案：它们不提供执行契约、事后语义验证或跨会话持久记忆；同时与抽象任务语言耦合弱，且 sim-to-real 因预测误差累积与未建模硬件噪声而脆弱。</p><p><strong>Agentic 系统</strong>：SayCan 用 affordance 给 LLM 计划打分，Inner Monologue 与 PaLM-E 把实时反馈注入主干做闭环重规划，Voyager 与 RoboAgent 引入终身技能库与反思。共同弱点是规划与执行通常处于同一进程或同一 API 边界内——执行失败时，无法区分是 LLM 决策差、中间工具调用处理不当、还是物理控制器没跟上命令。</p><p><strong>最接近的一类</strong>是具身智能体系统：ROSClaw 提供 ROS 2 能力发现、多模态观测归一化、动作校验与执行审计；RoboOS 用分层架构结合全局规划、本体特定技能与共享记忆；ABot-Claw 加入能力调度、持久多模态记忆与 critic 引导的重规划。作者对它们的批评是精确的四条：没有建立对齐任务意图、环境状态、执行证据与历史经验的<strong>统一认知状态空间</strong>；没有系统性地对物理结果做语义验证；试错循环没有通过验证后的固化来闭合；benchmark 与部署运行时分离，安全靠孤立机制而非分层架构。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>起点是那个抓空杯子的失败：每一层都对，合起来错。追问&quot;谁该负责发现这件事&quot;，答案是没有人——因为验证需要同时看到任务意图和物理结果，而这两样东西在现有栈里存在于不同的表示空间（符号工具调用 vs 压缩 latent vs 像素与关节角）。</p><p>于是问题从&quot;加一个验证模块&quot;变成&quot;先让意图和证据可比较&quot;。要可比较，就需要一个共享的状态表示；要跨进程共享且不引入代码依赖，最简单可靠的载体是文件系统。这个选择还顺带带来两个副产品：append-only 的审计轨迹由构造保证，以及语言无关的交互。</p><p>接着是粒度问题。单个动作太小，无法承载&quot;前置检查—监督执行—证据收集—验收&quot;这一整套；物理任务在时间上展开，靠校验孤立命令无法安全治理。于是把 <strong>session</strong> 提升为最小调度单元。</p><p>最后是学习。有了语义裁决，失败就从&quot;未标注轨迹&quot;变成&quot;带归因的负样本&quot;，自然可以沉淀。但作者加了一条纪律：只有经过再验证的修正才能进入知识库，避免&quot;提出过的恢复假设被当成事实记住&quot;。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>具身系统的失败常常不是模型不够聪明，而是没有任何一层负责判断&quot;世界是否真的变成了想要的样子&quot;。PhyAgentOS 把认知与物理之间的边界物化成一组人类可读的 Markdown 文件，让任务意图、能力约束、环境状态、执行证据活在同一个可比较的空间里；有了这个共同参照系，一个 verifier 才可能用证据而不是返回码来裁决成功、失败还是重规划，而被裁决过的经验才可能安全地积累。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以&quot;把杯子放进柜子&quot;为例走一遍。</p><p><strong>Agent 层：从目标到可执行 session</strong>。Goal Planner 把用户请求解析成任务目标并识别执行期间必须保持不变的约束。Goal Graph 与 Session Compiler 把目标分解成依赖感知的子任务结构（导航到柜子 → 抓杯子 → 开柜门 → 放入），每个可执行单元编译成一个 session。SkillRuntime-Target Selector 通过匹配所需能力、观测模态、动作语义与目标约束，决定&quot;怎么执行、在哪执行&quot;。规划不是只看用户请求：ContextBuilder 把请求与相关环境状态、先前尝试、可用能力、已恢复的 lessons 拼在一起；ToolRegistry 只暴露读状态、更新协议文档、查外部资源、发起受支持工作流这些结构化操作，Agent 拿不到 target SDK 的直接访问权。Agent 层的输出是一份 session 契约：任务目标、选定的 runtime 与 target、前置条件、执行上限、验收标准。</p><p><strong>协议层</strong>：<code>SESSIONS.md</code> 是架构的事务中心，记录唯一标识、任务目标、选定 runtime 与 target、前置条件、验收标准、生命周期状态与执行结果。<code>SKILLRUNTIME.md</code> 描述可复用的执行方法（所需观测、产出动作形式、编排模式、适配器要求），<code>TARGETS.md</code> 描述可用执行对象（类型、能力、观测模态、动作语义、端点、运行约束），二者共同定义兼容性两侧。<code>ENVIRONMENT.md</code> 存结构化环境快照（实体、关系、状态变化），让 Agent 能推理&quot;杯子在柜子里&quot;而不是直接操作像素流。<code>LESSONS.md</code> 记失败原因、纠正动作与 critic 反馈，<code>KNOWLEDGE.md</code> 存已验证的成功模式及其适用条件与来源。另有 <code>sensors.yaml</code>、<code>perception.yaml</code>、<code>runtime_contract.yaml</code>、<code>safety.yaml</code> 把部署期参数与语义任务状态分开。</p><p><strong>Runtime 层</strong>：四级链条 WatchdogSupervisor → SessionRunner → SkillRuntime → Target。Supervisor 是唯一监督入口，认领待处理 session、校验运行时契约、创建 runner、监控心跳、传播超时与取消、把终态结果写回；它刻意不执行观测—动作循环。执行前做<strong>兼容性预检</strong>，解析所需观测模态、动作表示、策略端点、目标能力、时序约束与安全配置能否构成有效执行路径，结果物化为 <code>AdapterPlan</code>（指定 PolicyAdapter、TargetAdapter、ActionBridge 链）与 <code>TargetToolManifest</code>（枚举本次 session 允许的目标操作）；无法产出有效计划的 session 在获得 target 访问权之前就被拒绝。</p><p><strong>两条执行流</strong>。策略驱动流：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">A</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm" style="margin-right:0.0139em;">Policy</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0813em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，runtime 反复取观测、转成模型输入、推理、转回标准动作表示、执行动作或动作块；Action Runtime 负责动作块缓冲、控制频率、截断、打断与重规划边界。Agent 直接工具流：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">Agent</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0813em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，通过受控的 <code>TargetSessionHandle</code> 做 observe / reset / invoke_tool / step / query_state，适合离散游戏交互与脚本化流程。两条流在同一个架构边界汇合——都由 session 创建、由 Supervisor 监督、以结构化证据包终止。</p><p><strong>SessionVerifier</strong>：终止后比对证据与契约，产出 success / failure / replan。证据包包含初始与终止观测、原始任务定义、对应的 <code>ENVIRONMENT.md</code> 快照、动作—观测历史、以及验收标准所需的目标原生事件或指标。作者强调保留初始状态的必要性：成功往往表示一个<strong>变化</strong>而非绝对条件，只看终止图片无法确定物体被移动过、容器被打开过。<code>replan</code> 的语义是原始尝试保持不可变，编译一个带更新前置条件的子 session，因而重规划创造新的可审计决策而不是改写历史。</p><p><strong>闭环自演化</strong>：Execute → Verify → Diagnose → Revise → Re-verify → Consolidate 六阶段。经验分三层组织：episodic（单次 session 的轨迹、证据、裁决、父子关系）、semantic（跨 episode 的稳定物体关系、复发失败模式、策略优劣条件）、methodological（跨足够多样初态仍有效的过程，可提升为技能规范注册进 <code>SKILLRUNTIME.md</code>）。检索时按当前目标、环境状态、target 类型与风险因子查询，并带上来源与作用域注入——在一个本体上学到的 lesson 不假设可迁移，除非前置条件与新 target 和场景匹配。</p><p><strong>分层安全</strong>：兼容性预检约束哪些组件组合可执行；action bridges 做坐标变换、单位归一化、关节重排、维度投影、夹爪重映射、动作块重采样这类确定性转换，畸形或欠定命令被拒绝而非静默修补；SafetyGuard 在转换后逐动作检查数据类型与维度、NaN 与无穷、关节与工作空间限制、速度加速度界、命令时长、动作频率、急停状态，每次干预都带结构化违规码写入证据，使安全干预在后续语义验证中可与策略错误区分；心跳监控处理进程停滞与网络分区；target-local 约束是最内层也是最权威的一层。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文以系统架构为主，形式化很少，但有两处值得展开。</p><p><strong>语义验收作为判决函数</strong>。verifier 实现的是</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal" style="margin-right:0.0822em;">V</span><span class="mopen">(</span><span class="mord mathnormal">G</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord text"><span class="mord texttt">success</span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord texttt">failure</span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord texttt">replan</span></span><span class="mclose">}</span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">G</span></span></span></span> 是任务目标与验收标准，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是初始与终止环境状态，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span> 是执行轨迹，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span> 是相关历史上下文。这个签名本身就是论文的主要论点：把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 显式放进定义域，等价于声明&quot;成功是一个状态<strong>转移</strong>谓词，不是终止状态的一元谓词&quot;。控制器返回码只能提供 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span> 的一个摘要，因而在定义上不足以计算 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0822em;">V</span></span></span></span>。作者明确指出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0822em;">V</span></span></span></span> 不必由单一模型实现——确定性谓词、任务特定评估器、多模态模型或工具辅助复核都可以藏在同一接口后，保持不变的是证据 schema 与裁决语义。</p><p><strong>两条执行流的形式对照</strong>。策略驱动流 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">A</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm" style="margin-right:0.0139em;">Policy</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0813em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 输出动作或动作块，Agent 编译完 session 后退出低层循环；Agent 直接流 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">Agent</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0813em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 输出的是受控句柄上的操作。两式的区别只在输出空间，输入签名相同——这正是它们能共享 session、监督、证据接口的形式依据。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>作者的评测组织成渐进式三层，认知层在三层之间保持不变，因而性能下降可以归因到具体层。</p><p><strong>游戏层：认知能否在物理被抽象掉时工作？</strong> 游戏引擎里动作被忠实执行，抓取总成功、导航不漂移、观测无传感器噪声，因此任务失败必然定位在认知层。Optimus-67（67 个长视野 Minecraft 任务，七组难度）上，PhyAgentOS 在 Wood 与 Stone 接近饱和（99%、96%），Iron 降到 52%（与最强基线相当），Gold 6%、Diamond 19%，最大相对优势在 RedStone 的 30%（超过所有报告基线），Armor 15%。作者把 RedStone 的优势归因于两点机制：SessionVerifier 能识别二值完成度量会判为失败的部分电路搭建，以及 Epistemic Memory 跨 session 保留并复用红石配方。StarDojo Lite-100 上用纯文本模型 deepseek-v4-flash 拿到 22.0% 整体成功率，高于 SPIKE 基线的 18.0%（作为参照，GPT-4.1 在同一 split 的多模态配置下是 12.7%）；成功集中在简单任务（56 个简单任务 37.5%，中等 3.7%，困难 0.0%，平均进展率 0.236，解出的任务平均 12.5 步）；最大提升在 Crafting，50.0% 对最强基线的 23.8%，归因于 <code>KNOWLEDGE.md</code> 里累积的已验证配方与 verifier 接受部分完成的合成序列。DST-Dojo（《饥荒》秋季第 0 天白天，10 个 episode）上平均存活从 1.02 天翻倍到 2.10 天（+106%），第 3 天存活率从 0% 到 30%，死于黑暗（Charlie）从 90% 降到 80%，饿死从 0% 升到 10%——作者诚实地解释后者是寿命延长后食物耗尽的结果，平均健康/饥饿/理智数值下降同理反映持续资源消耗而非退化。</p><p><strong>仿真层：策略在物理约束下能被救回多少？</strong> 三个 benchmark 统一用 First / Final 双协议，Final 表示 verifier 在失败后触发的一次受控恢复，策略权重、任务目标、成功判据都不变。LIBERO 上整体提升 OpenVLA +1.0、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> +0.4、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> +0.8、X-VLA +1.3 个百分点，增益不大是因为首次尝试成功率本来就高。CALVIN ABC→D 的五步链条暴露误差累积，全链完成率 X-VLA 74.3%→75.7%、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 38.9%→45.6%、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 85.3%→89.4%。RoboCasa365 的 target50 任务集（18 个原子技能 + 32 个复合活动，每任务 5 次随机试验共 250 episode）整体成功率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 17.6%→26.8%、RLDX-1 35.6%→42.8%、WorldDreamer 34.0%→42.4%，救回的 episode 分别是 23、18、21 个。跨 benchmark 的结论是：具身策略的许多失败不是根本性的任务误解，而是可被语义验证识别、可通过受控续行纠正的执行错误。</p><p><strong>真机层</strong>：在工业臂、桌面臂、双臂系统、四足与人形组成的机队上验证协议与安全机制。零样本跨本体迁移的验证方式是在 Franka、PIPER、Dobot 上执行相同任务规范，只换 session 配置里的 TargetAdapter 与 PolicyAdapter，认知层与协议文件不变。安全验证测三件事：注入故意不兼容的适配器配置，确认 Watchdog 在任何命令到达电机控制器之前拒绝每一个 session；注入违反工作空间界或速度限的动作块，确认 SafetyGuard 拦截并钳制；测量从违规被检测到电机停止的急停延迟。</p><p>作者自己在 §6.2 承认真机部分强调安全关键验证而非大规模任务完成统计，完整的渐进流水线只在代表性本体上演示过，尚未扩展到架构理论上支持的机队级多样性。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：具身栈的三条主线各解决一部分问题，但没有任何一层负责验证物理结果，导致&quot;执行终止&quot;被当成&quot;任务完成&quot;。PhyAgentOS 把认知与物理的边界做成文件系统，用嵌入 YAML 的 Markdown 物化跨层状态，由构造得到可审计、可版本化的执行记录且两层间无代码依赖。以 session 而非动作为最小调度单元，让兼容性预检、心跳、取消、重试、证据收集、结果写回可以一致地施加。SessionVerifier 用证据包而非返回码裁决 success/failure/replan，验证过的结果经 epistemic memory 固化成可复用知识与纠正性教训，闭合试错循环而不重训任何神经模型。评测走游戏→仿真→真机的渐进路径且认知层保持不变，在 Optimus-67、StarDojo、DST-Dojo 上验证认知能力，在 LIBERO、CALVIN、RoboCasa365 上对多种 VLA 后端一致带来增益。</p><p><strong>3 句话版</strong>：具身系统的核心缺口是没人负责判断意图是否在物理上实现。PhyAgentOS 用文件协议建立统一认知状态空间，让 verifier 能用证据裁决语义完成，并把裁决过的经验沉淀成可检索知识。在不改策略权重的前提下，它对 LIBERO/CALVIN/RoboCasa365 上的每个 VLA 后端都提升了最终成功率。</p><p><strong>1 句话版</strong>：给具身智能补上&quot;验收&quot;这一层，很多看似模型能力不足的失败其实是可恢复的执行错误。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>SessionVerifier 的裁决足够可靠，可以作为学习信号使用</strong>。整个自演化循环的价值全部继承自这个裁决——<code>KNOWLEDGE.md</code> 与 <code>LESSONS.md</code> 的内容由它决定，benchmark 报告的 Final 成绩由它触发，&quot;经验固化&quot;的纪律（只有再验证过的修正才入库）也以它为前提。如果 verifier 本身有偏，那么不是简单地少纠正一些失败，而是<strong>系统性地把错误固化成知识</strong>，并且这些错误还会通过检索污染后续所有相关 session 的规划上下文。</p><p>它在实践中可能不成立，原因是 verifier 至少部分由多模态模型实现，而&quot;从初始与终止图像判断杯子是否被放进柜子&quot;正是这类模型已知不可靠的任务（遮挡、视角、细粒度空间关系）。更麻烦的是失败模式的方向性：verifier 更可能在&quot;看起来像成功&quot;的场景上误判为成功，而这恰好与 §1 那个抓空杯子的原始动机是同一类错误——只不过从控制器层挪到了验证层。</p><p>论文为它提供的证据是间接的。作者明确指出 verifier 可以&quot;推翻假阴性的完成判定&quot;，并把 RedStone 与 Crafting 上的优势部分归因于&quot;接受部分完成的序列&quot;——这两处恰恰说明 verifier 的判据比环境的二值信号<strong>更宽松</strong>。在 RoboCasa365 上作者说明成功由环境完成信号度量，这是一个独立的检查；但在游戏层与 LIBERO/CALVIN 的部分结论里，verifier 既是干预的触发者又参与结果解释。缺的证据是：verifier 裁决与人工判定在一个有代表性样本上的一致率，以及假阳性/假阴性的分别统计。论文报告了 §5.3 的安全性量化协议，却没有给出 verifier 自身的准确率。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不复现整个 OS，只测那条最脆弱的假设。</p><ul><li><strong>数据</strong>：从 LIBERO 或 RoboCasa365 里取 200 个 episode，其中 100 个环境判定成功、100 个判定失败（后者刻意覆盖多种失败：抓空、放错位置、中途碰倒、超时）。每个 episode 保存初始观测、终止观测、任务描述、动作—观测历史摘要。</li><li><strong>实现</strong>：只实现 verifier 这一环。用一个多模态模型按论文的证据包格式（初始状态 + 终止状态 + 任务定义 + 轨迹摘要）产出 success/failure/replan。做两个对照：只给终止观测的版本，以及只给控制器返回码的版本。</li><li><strong>测量</strong>：以环境完成信号为参考，报告三个版本的准确率、假阳性率、假阴性率；并让 2 名标注者对分歧样本人工判定，计算与人判的一致率（Cohen&#39;s kappa）。</li><li><strong>判据</strong>：若完整证据包版本的假阳性率显著低于只看终止观测的版本，则支持论文&quot;必须保留初始状态&quot;的设计论点。若完整版本的假阳性率仍在 15% 以上，则自演化循环存在把错误固化为知识的现实风险，<code>KNOWLEDGE.md</code> 的写入需要额外的多次一致性门槛，而不能靠单次裁决。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最强的攻击是给仿真层的增益一个替代解释：<strong>Final 相对 First 的提升，大部分来自&quot;多给了一次尝试机会&quot;，而不是来自语义验证的诊断质量</strong>。</p><p>实验设计很直接：在同样的 benchmark 上加一个 <strong>naive retry</strong> 基线——失败后不做任何诊断，不生成恢复指令，只是让同一策略从当前物理状态继续 rollout 同样的额外步数。如果 naive retry 在 RoboCasa365 上也能拿到接近 +7 到 +9 个百分点，那么 SessionVerifier 的诊断与恢复指令生成就不是关键，关键是额外的执行预算与&quot;不 reset 环境&quot;这个协议选择。论文报告了每个后端救回的 episode 数（23/18/21），但没有报告 naive retry 的对照，这是当前证据链上最明显的空洞。</p><p>第二类攻击针对<strong>可预测的失效条件</strong>：文件协议是轮询的。作者在 §6.2 自己承认 Watchdog 周期性读 <code>SESSIONS.md</code>、Agent 轮询协议文件更新，延迟正比于轮询间隔，并指出&quot;真机场景下 Watchdog 必须在毫秒级响应安全违规&quot;。这意味着安全论证存在一个结构性张力：SafetyGuard 在动作边界同步拦截所以不受影响，但<strong>心跳监控</strong>这条防线的响应下界由轮询间隔决定。可以设计一个压力测试：在真机上人为让 policy service 挂起，测量从挂起到执行路径被终止的时间分布，并把它与本体自身看门狗的响应时间对比。如果系统级心跳明显慢于本体本地保护，那么&quot;分层安全&quot;里 PhyAgentOS 贡献的那几层在最危险的故障类型上其实是冗余的。</p><p>第三点针对游戏层的结论。作者把 StarDojo 上的 22.0% 与 SPIKE 的 18.0% 直接对比，但两者用的 backbone 不同（deepseek-v4-flash vs Qwen3.5-397B / Gemini-3.1-pro / GPT5.4），且 PhyAgentOS 是纯文本配置。要把增益归给系统而非模型，需要在同一 backbone 上跑 SPIKE 与 PhyAgentOS 的对照。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>论文把 world model 定位成&quot;外部推理资源&quot;，并在 §6.3 提出未来可以让它为 verifier 提供 look-ahead rollout，在投入物理资源之前预测 session 是否可能达成目标。这个方向本身是增量的（把预测模块插进现有循环）。更有意思的重构在另一个方向。</p><p><strong>驱动局限</strong>：PhyAgentOS 的验收标准是 Agent 在编译 session 时<strong>写死</strong>的自然语言条件，verifier 事后照着判。这意味着系统能学会更好的方法、避开已知失败，却学不会<strong>更好的验收标准</strong>。而 §9 指出的最大风险恰恰是验收标准本身可能是错的——一个宽松的判据会让所有下游学习朝错误方向漂移。论文在 §4.3 提到&quot;精化验收条件&quot;是自演化的一部分，但没有给出机制。</p><p><strong>可借鉴的相邻领域</strong>：形式化方法里的 <strong>specification mining</strong>（从执行轨迹归纳出不变式），以及软件工程里的<strong>变异测试</strong>（用人为注入的缺陷检验测试集能否发现它们）。这两套工具专门处理&quot;判据本身是否够强&quot;这个问题，而不是&quot;实现是否满足判据&quot;。</p><p><strong>新的 framing</strong>：把验收标准当成一等的、可学习、可被检验的对象。系统不只积累&quot;怎么做&quot;，还积累&quot;怎么判&quot;，并且用变异测试式的方法主动评估每条判据的鉴别力——把已知失败的 episode 喂给判据，看它能否被拒绝。</p><p><strong>第一个实验</strong>：在 RoboCasa365 上，为每个任务收集一批人工标注的<strong>近似成功</strong>样本（杯子放在柜子边缘、门只开了一半、物体放对位置但姿态错误）。对每条现有验收标准计算&quot;变异分数&quot;：这批近似成功样本中被正确拒绝的比例。然后让 Agent 在看到被漏判的样本后改写验收标准，重新计算变异分数。如果变异分数能被系统性提高，且提高后 verifier 在独立测试集上的假阳性率同步下降，就说明&quot;学习判据&quot;是一个可操作的独立能力，值得从&quot;学习方法&quot;里分离出来单独建模。</p>',62)])])}const d=a(e,[["render",l]]);export{h as __pageData,d as default};
